import pathlib
p = pathlib.Path('/private/tmp/claude-501/-Users-guillaumeloulier-PhpstormProjects-oss-elephc--claude-worktrees-streams-csv-signature/c8dbe38f-1f79-484f-9b83-62bacab9ca56/scratchpad/obj/copy_samefile.py')
t = p.read_text()
t = t.replace(
    '''    emitter.instruction(&emitter.platform.stat_dev_load_instr("x9", "sp", src_stat + dev_off));
    emitter.instruction(&emitter.platform.stat_dev_load_instr("x10", "sp", dst_stat + dev_off));''',
    '''    // Darwin stores st_dev as a signed 32-bit int, so only a word of it is the device.
    let dev_reg = if emitter.platform.stat_dev_is_narrow() { ("w9", "w10") } else { ("x9", "x10") };
    emitter.instruction(&format!("ldr {}, [sp, #{}]", dev_reg.0, src_stat + dev_off));
    emitter.instruction(&format!("ldr {}, [sp, #{}]", dev_reg.1, dst_stat + dev_off));''')
t = t.replace('    emitter.instruction("cmp x9, x10");\n    emitter.instruction("b.ne __rt_copy_not_same_file");                        // same inode on another device',
              '    emitter.instruction(&format!("cmp {}, {}", dev_reg.0, dev_reg.1));\n    emitter.instruction("b.ne __rt_copy_not_same_file");                        // same inode on another device')
t = t.replace('''    emitter.instruction(&format!("mov r10, QWORD PTR [rbp - {}]", src_stat - dev_off));
    emitter.instruction(&format!("cmp r10, QWORD PTR [rbp - {}]", dst_stat - dev_off));''',
              '''    // Darwin stores st_dev as a signed 32-bit int, so only a word of it is the device.
    let (dev_reg, dev_ptr) = if emitter.platform.stat_dev_is_narrow() {
        ("r10d", "DWORD")
    } else {
        ("r10", "QWORD")
    };
    emitter.instruction(&format!("mov {}, {} PTR [rbp - {}]", dev_reg, dev_ptr, src_stat - dev_off));
    emitter.instruction(&format!("cmp {}, {} PTR [rbp - {}]", dev_reg, dev_ptr, dst_stat - dev_off));''')
p.write_text(t)
print('narrow-device handling in place')
